//
//  AppShortcutPhraseTests.swift
//  AbbayTests
//

@testable import Abbay
import XCTest

/// Reads the App Shortcut phrases the build actually ships (`Metadata.appintents`, generated by the
/// App Intents compiler from `AbbayAppShortcuts`), so the assertions cover what Siri is given rather
/// than a copy of the source.
final class AppShortcutPhraseTests: XCTestCase {
    private static let appName = "${applicationName}"

    /// "Play <book> on Abbay" used to match no Abbay phrase -- every phrase said "in Abbay" -- so
    /// Siri treated it as a generic media request and played it in the default music app.
    func test_everyInAppNamePhrase_hasOnAndUsingVariants() throws {
        let phrases = try Self.shippedPhrases().flatMap(\.phrases)
        let inPhrases = phrases.filter { $0.contains("in \(Self.appName)") }
        XCTAssertFalse(inPhrases.isEmpty, "expected the existing \"in Abbay\" phrases")

        for phrase in inPhrases {
            let on = phrase.replacingOccurrences(of: "in \(Self.appName)", with: "on \(Self.appName)")
            XCTAssertTrue(phrases.contains(on), "missing \"\(on)\" for \"\(phrase)\"")
        }
        XCTAssertTrue(phrases.contains("Play \(Self.appName)"), "missing \"Play Abbay\"")
        XCTAssertTrue(
            phrases.contains("Play ${audiobook} using \(Self.appName)"),
            "missing \"Play <book> using Abbay\""
        )
    }

    /// Apple caps an app at 1,000 App Shortcut phrases counting every parameter permutation; past
    /// it, phrases are silently dropped. Entity phrases expand to one phrase per suggested entity.
    func test_phraseBudget_staysUnderApplesLimit() throws {
        var total = 0
        for phrase in try Self.shippedPhrases().flatMap(\.phrases) {
            if phrase.contains("${audiobook}") {
                total += AudiobookEntityQuery.suggestionLimit
            } else if phrase.contains("${chapter}") {
                total += ChapterEntityQuery.suggestionLimit
            } else {
                total += 1
            }
        }
        XCTAssertLessThanOrEqual(total, 1000, "App Shortcut phrase permutations: \(total)")
    }

    // MARK: - Helpers

    private struct Shortcut {
        let action: String
        let phrases: [String]
    }

    private static func shippedPhrases() throws -> [Shortcut] {
        let url = try XCTUnwrap(
            Bundle(for: MediaListViewModel.self).url(
                forResource: "extract",
                withExtension: "actionsdata",
                subdirectory: "Metadata.appintents"
            ),
            "Metadata.appintents/extract.actionsdata missing from the app bundle"
        )
        let json = try XCTUnwrap(
            JSONSerialization.jsonObject(with: Data(contentsOf: url)) as? [String: Any]
        )
        let shortcuts = try XCTUnwrap(json["autoShortcuts"] as? [[String: Any]])
        return shortcuts.map { shortcut in
            let templates = shortcut["phraseTemplates"] as? [[String: Any]] ?? []
            return Shortcut(
                action: shortcut["actionIdentifier"] as? String ?? "",
                phrases: templates.compactMap { $0["key"] as? String }
            )
        }
    }
}
